<script setup>
import { ref } from 'vue';
import { toggleSidebar } from "./store";
import { getProfile, user } from "~/js/fetchUserProfile";
import { getKey, encryptData } from '~/encrpyt';
import { clearAsoStorage, getToken } from '~/js/cryptoToken';
import { fetchSysDescription, sysdescription} from '~/js/fetchMenu';
const router = useRouter();
const userImage = ref("")
const isImageError = ref(false)
const isLoading = ref(false);

function getUserImage(userId, employeeId) {
  try {
    isLoading.value = true;
    const imageUrl = `https://apps.fastlogistics.com.ph/fpma2api/api/Access/get-employee-picture?userid=${userId}&empid=${employeeId}`
    const img = new Image()

    img.onload = () => {
      userImage.value = imageUrl
      isImageError.value = false
      isLoading.value = false;
    }

    img.onerror = () => {
      isImageError.value = true
      console.error("Failed to load user image.")
    }

    img.src = imageUrl
  } catch (error) {
    console.error("Error fetching user image:", error)
    isImageError.value = true
  }
}
watch(sysdescription, (newTitle) => {
  if (newTitle) {
    useHead({
      title: newTitle,
      meta: [{ name: 'ASO', content: newTitle }],
      link: [
        {
          rel: 'icon',
          type: 'image/png',
         href:"data:image/png;base64,"
         },
      ],
    });
  }
});
const isDropdownOpen = ref(false);
const dropdownRef = ref(null);
const handleClickOutside = (event) => {
  if (isDropdownOpen.value && dropdownRef.value && !dropdownRef.value.contains(event.target)) {
    isDropdownOpen.value = false;
  }
};
function toggleDropdown() {
  isDropdownOpen.value = !isDropdownOpen.value;
}


function Logout() {
  clearAsoStorage();
  // Delete cookie
  document.cookie = "_sys_pref_cache=; path=/; expires=Thu, 01 Jan 1970 00:00:00 GMT;";
  router.push('/')
}

function Dashboard() {
  isDropdownOpen.value = false;
  router.push('/main/dashboard')
}

